begin;
create or replace function public.apply_shop_event(p_event_id text,p_event_type text,p_event_created bigint,p_livemode boolean,p_data jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_order public.shop_orders%rowtype;v_count integer;v_status text;v_item record;
begin
  insert into public.stripe_events(event_id,event_type,event_created,livemode) values(p_event_id,p_event_type,p_event_created,p_livemode) on conflict do nothing;
  get diagnostics v_count=row_count;
  if v_count=0 then return jsonb_build_object('duplicate',true);end if;
  if p_data->>'kind'='shop_refund' then
    select * into v_order from public.shop_orders where stripe_payment_intent_id=p_data->>'payment_intent_id' for update;
    if not found then return jsonb_build_object('ignored',true);end if;
    if v_order.livemode<>p_livemode then raise exception 'Order mode mismatch';end if;
    update public.shop_orders set refunded_cents=greatest(refunded_cents,least(amount_cents,(p_data->>'refunded_cents')::integer)),status=case when (p_data->>'refunded_cents')::integer>=amount_cents then 'refunded' else 'partially_refunded' end,updated_at=now() where id=v_order.id;
    return jsonb_build_object('processed',true);
  end if;
  select * into v_order from public.shop_orders where id=(p_data->>'order_id')::uuid for update;
  if not found or v_order.livemode<>p_livemode then raise exception 'Order mismatch';end if;
  if v_order.checkout_session_id is not null and v_order.checkout_session_id<>p_data->>'session_id' then raise exception 'Session mismatch';end if;
  if p_data->>'currency'<>'eur' then raise exception 'Currency mismatch';end if;
  -- Stripe Tax can add tax after Checkout. Never accept a total below the reserved subtotal+shipping.
  if (p_data->>'amount_cents')::integer<v_order.amount_cents then raise exception 'Amount mismatch';end if;
  v_status:=p_data->>'status';
  if v_order.status in ('paid','partially_refunded','refunded') then v_status:=v_order.status;end if;
  if v_status in ('failed','expired') and not v_order.inventory_released then
    for v_item in select product_id,quantity from public.shop_order_items where order_id=v_order.id loop
      update public.catalog_products set stock=stock+v_item.quantity where id=v_item.product_id and stock is not null;
    end loop;
  end if;
  if v_order.inventory_released and v_status='paid' then raise exception 'Paid order inventory previously released';end if;
  update public.shop_orders set status=v_status,checkout_session_id=p_data->>'session_id',
    stripe_payment_intent_id=coalesce(p_data->>'payment_intent_id',stripe_payment_intent_id),
    amount_cents=(p_data->>'amount_cents')::integer,
    donor_name=coalesce(p_data->>'name',donor_name),donor_email=coalesce(p_data->>'email',donor_email),
    shipping_details=coalesce(nullif(p_data->'shipping_details','null'::jsonb),shipping_details),
    inventory_released=inventory_released or v_status in ('failed','expired'),
    paid_at=case when v_status='paid' then coalesce(paid_at,to_timestamp(p_event_created)) else paid_at end,updated_at=now()
    where id=v_order.id;
  update public.shop_orders o set refunded_cents=least(o.amount_cents,r.refunded_cents),status=case when r.refunded_cents>=o.amount_cents then 'refunded' else 'partially_refunded' end
    from public.stripe_refund_totals r where o.id=v_order.id and o.stripe_payment_intent_id=r.payment_intent_id and o.livemode=r.livemode and r.refunded_cents>0;
  return jsonb_build_object('processed',true);
end;
$$;
insert into public.site_pages(slug,title,blocks,published) values
('privacy', '{"en":"Privacy notice"}'::jsonb, '[{"type":"text","text":{"en":"KINDORA PAWS · LAST UPDATED 13 OCTOBER 2026"}},{"type":"heading","text":{"en":"Who is responsible"}},{"type":"text","text":{"en":"The legal organisation, registered address and identification details will be published before donations open."}},{"type":"text","text":{"en":"For privacy questions or requests, contact the organisation listed in the transparency section."}},{"type":"heading","text":{"en":"Information used"}},{"type":"text","text":{"en":"When you donate, the organisation receives your name and email, donation amount and currency, payment status, transaction references, frequency, language, and any optional programme-update preference. Stripe collects your payment details directly. This website does not collect or store card numbers or security codes."}},{"type":"text","text":{"en":"Technical protection uses a salted hash of the connecting IP address to limit checkout requests. Short-lived rate-limit records are removed when the next checkout request runs. Hosting providers may keep separate operational security logs."}},{"type":"heading","text":{"en":"Purposes and grounds"}},{"type":"text","text":{"en":"Donation and payment records are used to administer your gift and monthly support, maintain accounts, resolve payment issues and prevent abuse. The organisation relies on the donation arrangement, applicable accounting obligations and legitimate security interests as appropriate. Optional programme communications and marketing tracking require your separate consent. Refusing either does not prevent you from donating."}},{"type":"heading","text":{"en":"Providers and international processing"}},{"type":"text","text":{"en":"Stripe processes payments; Supabase stores donation records and provides the secure application service. The website’s hosting provider processes technical requests. If you accept marketing cookies and the organisation enables campaign tracking, Google and Meta receive campaign and conversion information. Donor names, email addresses and private confirmation tokens are not included in the implemented marketing events."}},{"type":"text","text":{"en":"The organisation will publish the applicable processing locations and safeguards for international transfers before donations open."}},{"type":"heading","text":{"en":"Retention"}},{"type":"text","text":{"en":"The organisation will publish its donation-record retention period and accounting requirements before donations open."}},{"type":"text","text":{"en":"Language preferences, cookie choices and conversion deduplication references use browser storage. Cookie choices are requested again after six months. A private confirmation token may remain in your browser tab’s session storage until the tab is closed. You can clear this storage using your browser settings."}},{"type":"heading","text":{"en":"Your choices and rights"}},{"type":"text","text":{"en":"Where applicable, you may request access, correction, erasure, restriction or portability of your personal information and object to certain uses. You can withdraw optional consent at any time. Contact the organisation above to exercise these rights or stop programme updates. You may also complain to your local data protection authority. Some payment records may need to be retained for legal obligations."}},{"type":"heading","text":{"en":"Cookies and advertising"}},{"type":"text","text":{"en":"Essential browser storage keeps your language and confirmation flow working. Optional Google and Meta scripts are loaded only after you choose “Accept optional”. Choose “Essential only” to refuse them, or reopen your choices below. Changing your choice stops future optional tracking; information already received by providers remains subject to their policies."}},{"type":"heading","text":{"en":"Security and automated processing"}},{"type":"text","text":{"en":"Donation records are restricted to authorised administration and server processes. The service does not make automated decisions producing legal or similarly significant effects about donors. Payment providers operate their own fraud and authentication systems."}},{"type":"text","text":{"en":"See also the donation terms."}}]'::jsonb, false),
('donation-terms', '{"en":"Donation terms"}'::jsonb, '[{"type":"text","text":{"en":"KINDORA PAWS · VERSION 2026-10-13-V1"}},{"type":"heading","text":{"en":"The recipient"}},{"type":"text","text":{"en":"The legal recipient, registration details and address will be published before donations open."}},{"type":"text","text":{"en":"Questions and refund requests can be sent to the organisation’s published contact."}},{"type":"heading","text":{"en":"Your donation"}},{"type":"text","text":{"en":"A donation is a voluntary gift to support food, necessary medicines, veterinary attention and daily shelter care. It is not a purchase of goods or services, an investment, or a promise of a financial return. No adoption entitlement is created by donating."}},{"type":"text","text":{"en":"Gifts are pooled for the programme’s needs. Illustrated animals and care categories do not create an earmarked donation for a specific animal or treatment. Payment-processing fees and necessary programme running costs may reduce the amount available for care."}},{"type":"heading","text":{"en":"Currency and payment"}},{"type":"text","text":{"en":"All charges are in euros. Your bank or payment provider may apply currency-conversion or other fees. Stripe supplies the secure checkout and determines which payment methods are eligible for your country, device and donation type."}},{"type":"text","text":{"en":"A donation is confirmed only after payment confirmation is received. Returning to the confirmation page alone does not confirm a payment. Some local payment methods can remain pending while the payment provider processes them."}},{"type":"heading","text":{"en":"Monthly donations"}},{"type":"text","text":{"en":"Choosing “Give monthly” authorises a recurring donation for the selected amount each month until cancelled. There is no free trial. You can manage payment details and cancel future payments through the secure Stripe portal reached from your confirmation page, or contact the organisation if you no longer have the link. Cancellation does not automatically refund earlier completed donations."}},{"type":"heading","text":{"en":"Refunds and payment problems"}},{"type":"text","text":{"en":"Contact the organisation promptly if a donation was accidental, duplicated, unauthorised or incorrect. Include your transaction reference and avoid sending full card details. Requests are assessed according to the circumstances, payment-provider rules and applicable legal rights. Accepted refunds are returned through the original payment method where supported. The time required depends on the provider."}},{"type":"heading","text":{"en":"Receipts and tax"}},{"type":"text","text":{"en":"A payment receipt confirms the payment; it is not automatically a charitable tax certificate. Tax deductibility depends on the recipient’s legal status and your country. No tax benefit is promised by this website."}},{"type":"heading","text":{"en":"Programme information and imagery"}},{"type":"text","text":{"en":"The legal recipient and contact details appear in the transparency section. The current photos are clearly labelled AI-generated illustrations. They do not document real dogs, treatments, testimonials or rescue cases. The website does not claim government affiliation or registered charity status without the organisation supplying the corresponding verified information."}},{"type":"heading","text":{"en":"Privacy"}},{"type":"text","text":{"en":"The privacy notice explains donation records, providers, storage and optional marketing choices. Optional communications and advertising consent are separate from your donation."}},{"type":"heading","text":{"en":"Applicable rights and changes"}},{"type":"text","text":{"en":"These terms do not remove rights that cannot be excluded under applicable law. The version presented when you donate is recorded with your donation. Material changes affecting recurring donations should be communicated by the organisation before they take effect."}}]'::jsonb, false),
('purchase-terms', '{"en":"Purchase terms"}'::jsonb, '[{"type":"text","text":{"en":"The seller’s legal identity and contact details must be completed in the organisation section before product checkout opens."}},{"type":"heading","text":{"en":"Products and donations"}},{"type":"text","text":{"en":"Physical and digital products are purchases. Support items and monthly plans are voluntary gifts governed by the separate donation terms. A product purchase is not represented as a tax-deductible donation."}},{"type":"heading","text":{"en":"Price and payment"}},{"type":"text","text":{"en":"Prices are in euros and set as tax-inclusive. Applicable delivery charges and the final total are shown before payment in Stripe Checkout. Payment is confirmed only after the provider’s notification. Published product descriptions identify the product sold."}},{"type":"heading","text":{"en":"Delivery"}},{"type":"text","text":{"en":"Physical delivery is available only to the countries offered at checkout. The seller is responsible for dispatch, delivery estimates and providing tracking where available. Digital delivery links appear on the private order-confirmation page after payment. Contact the seller if delivery is unavailable or delayed."}},{"type":"heading","text":{"en":"Returns and applicable rights"}},{"type":"text","text":{"en":"Where EU distance-selling protections apply, consumers generally have a 14-day withdrawal period for eligible purchases, subject to legal exceptions. Your statutory rights concerning faulty or misdescribed products remain applicable. Contact the seller to request a return, refund or resolve a problem."}},{"type":"text","text":{"en":"This implementation does not collect the specific consent and acknowledgement required to waive withdrawal for immediately supplied digital content. The seller must honour applicable withdrawal rights or implement the required process before relying on such an exception."}},{"type":"heading","text":{"en":"Contact"}},{"type":"text","text":{"en":"Use the seller’s published contact and include your order reference. Do not send full card details."}},{"type":"heading","text":{"en":"Additional purchase and delivery conditions"}},{"type":"text","text":{"en":"Additional conditions will be published by the seller."}},{"type":"text","text":{"en":"See also the privacy notice."}}]'::jsonb, false) on conflict(slug) do nothing;
commit;
